import{H as e,V as t,et as n,j as r}from"./chunks/framework.B_YhZOsv.js";var i=JSON.parse(`{"title":"Upload Lifecycle","description":"","frontmatter":{},"headers":[],"relativePath":"upload-lifecycle.md","filePath":"upload-lifecycle.md"}`),a={name:`upload-lifecycle.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="upload-lifecycle" tabindex="-1">Upload Lifecycle <a class="header-anchor" href="#upload-lifecycle" aria-label="Permalink to “Upload Lifecycle”">​</a></h1><p>This page documents exactly what <code>status</code> transitions happen, and in what order, for every outcome an upload can have — including the cases that tend to surprise people: a chunk failing partway through, cancelling mid-upload, and what actually happens when you retry after a failure.</p><h2 id="status-state-machine" tabindex="-1">Status state machine <a class="header-anchor" href="#status-state-machine" aria-label="Permalink to “Status state machine”">​</a></h2><table tabindex="0"><thead><tr><th>From</th><th>To</th><th>Trigger</th></tr></thead><tbody><tr><td><em>(none)</em></td><td><code>uploading</code></td><td><code>addFile</code> adds the file to <code>files</code> and starts the request</td></tr><tr><td><code>uploading</code></td><td><code>processing</code></td><td>All bytes have been sent (<code>uploadProgress</code> reaches 100) and the hook is waiting on the server&#39;s response</td></tr><tr><td><code>uploading</code> / <code>processing</code></td><td><code>done</code></td><td>The server responds with a <code>2xx</code> status</td></tr><tr><td><code>uploading</code> / <code>processing</code></td><td><code>error</code></td><td>A network error, a non-<code>2xx</code> response, a <code>beforeUpload</code>/<code>onUploadRetry</code> rejection, or a cancellation</td></tr><tr><td><code>error</code></td><td><code>uploading</code></td><td><code>retryUpload(id)</code> is called</td></tr></tbody></table><p><code>idle</code> exists as a type but isn&#39;t a state you&#39;ll ever observe in <code>files</code> — every file is already <code>uploading</code> by the time <code>addFile</code> adds it to the list. <code>done</code> and <code>error</code> are terminal: the only way out of <code>error</code> is <code>retryUpload</code>, and there&#39;s no way out of <code>done</code> at all.</p><h2 id="when-a-chunk-fails" tabindex="-1">When a chunk fails <a class="header-anchor" href="#when-a-chunk-fails" aria-label="Permalink to “When a chunk fails”">​</a></h2><p>Each chunk is retried independently, up to <code>fileChunking.maxChunkRetries</code> (default <code>2</code>) <strong>additional</strong> attempts, reusing the same <code>uploadId</code> and <code>chunkIndex</code> — earlier, already-succeeded chunks are not re-sent.</p><p>Once a chunk exhausts its retries, the <strong>entire upload</strong> fails: <code>status</code> becomes <code>&quot;error&quot;</code>, <code>onUploadError</code> fires with the underlying error, and no later chunks are attempted. There&#39;s no partial-success state — a file is either fully <code>done</code> or it&#39;s <code>error</code>, even if 9 of 10 chunks made it through. A later <code>retryUpload</code> call can pick up from exactly this point — see below.</p><h2 id="cancelling-mid-upload" tabindex="-1">Cancelling mid-upload <a class="header-anchor" href="#cancelling-mid-upload" aria-label="Permalink to “Cancelling mid-upload”">​</a></h2><p>Only one request is ever in flight per file at a time — for a chunked upload, that&#39;s whichever chunk is currently sending. Calling <code>removeFile(id)</code> (or unmounting the component, which aborts everything still in flight) aborts that request immediately.</p><p>A cancellation is <strong>never retried</strong>, even if the chunk still has retry attempts left — it&#39;s treated as intentional and propagates straight through as an <code>UploadCancelledError</code>, without pausing at intermediate chunks either. <code>removeFile</code> also removes the item from <code>files</code> in the same call, so by the time <code>onUploadError</code>/<code>onUploadFinish</code> fire for the cancellation, the file is already gone from the tracked list — don&#39;t rely on reading it back out of <code>files</code> from inside those callbacks.</p><h2 id="retryupload-resumes-a-chunked-upload-—-it-doesn-t-restart" tabindex="-1"><code>retryUpload</code> resumes a chunked upload — it doesn&#39;t restart <a class="header-anchor" href="#retryupload-resumes-a-chunked-upload-—-it-doesn-t-restart" aria-label="Permalink to “retryUpload resumes a chunked upload — it doesn&#39;t restart”">​</a></h2><p>For a chunked upload, <code>retryUpload</code> picks up at the chunk that failed instead of starting the whole file over: it reuses the same <code>uploadId</code> and begins again at that <code>chunkIndex</code>, so chunks that already succeeded aren&#39;t re-sent. <code>uploadProgress</code> reflects the resumed starting point immediately, rather than resetting to <code>0</code> and jumping back up once the resumed chunk&#39;s first progress event arrives.</p><p>This works without any changes to your server: the chunk-endpoint contract already keys chunks by <code>uploadId</code> + <code>chunkIndex</code> and reassembles once every index has arrived (see <a href="/useCourier/backend-integration.html">Backend Integration</a>), so resuming under the same <code>uploadId</code> looks identical to the server as a slower single attempt — nothing is orphaned.</p><p>For a non-chunked (whole-file) upload there&#39;s no partial progress to resume from, so <code>retryUpload</code> re-sends the entire file, same as it always has.</p><p><strong>This only covers retrying within the same page session.</strong> If the user reloads the page mid-upload instead of clicking retry, everything is lost: all upload state lives only in React state and an in-memory ref, so nothing survives a reload. A fresh <code>addFile</code> call after reloading is indistinguishable from uploading the file for the first time — new <code>id</code>, new <code>uploadId</code> if it&#39;s chunked — and the bytes already sent before the reload are abandoned server-side. There is currently no support for resuming an upload across a page reload, only across a manual retry in the same session.</p>`,16)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};